// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x1);
        vm.deal(user, 10 wei);
        vm.prank(user);
        c.deposit{value: 10 wei}();

        address recipient = address(0x2);
        c.migrateTo(recipient);

        assertTrue(address(c).balance == 0, "contract balance should be 0 after correct migration");
    }
}
